head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Verify
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand('assert', 'true', 'true');
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create by Truong.Luu
    //Create date 05-Feb-2018
    //unitTest();
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
